}

:root:not(.dn-day) #world_popup_entries_list .world_entry .killSwitch.fa-toggle-off::before,
:root:not(.dn-day) #completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action.fa-toggle-off::before {
